// Serves the repro pages on http://localhost:<port> (default 8123), plus
// `/bytes/<n>`, which streams `n` generated bytes without touching the disk.
//
//   node browser-bugs/serve.mjs [port]

import { createServer } from 'node:http';
import { createReadStream, statSync } from 'node:fs';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('.', import.meta.url));
const PORT = Number(process.argv[2]) || 8123;
const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json',
  '.md': 'text/markdown; charset=utf-8',
};

function serveBytes(res, size) {
  res.writeHead(200, {
    'content-type': 'application/octet-stream',
    'content-length': size,
    'cache-control': 'no-store',
  });
  const CHUNK = 1024 * 1024;
  const block = Buffer.alloc(CHUNK);
  for (let i = 0; i < CHUNK; i++) block[i] = i & 0xff;
  let sent = 0;
  const pump = () => {
    while (sent < size) {
      const n = Math.min(CHUNK, size - sent);
      sent += n;
      if (!res.write(n === CHUNK ? block : block.subarray(0, n))) {
        res.once('drain', pump);
        return;
      }
    }
    res.end();
  };
  pump();
}

createServer((req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost');
  const bytes = pathname.match(/^\/bytes\/(\d+)$/);
  if (bytes) return serveBytes(res, Number(bytes[1]));
  let path = normalize(join(ROOT, decodeURIComponent(pathname)));
  if (!path.startsWith(ROOT)) return res.writeHead(403).end();
  try {
    if (statSync(path).isDirectory()) path = join(path, 'index.html');
    statSync(path);
  } catch {
    return res.writeHead(404).end('Not found');
  }
  res.writeHead(200, {
    'content-type': TYPES[extname(path)] || 'application/octet-stream',
    'cache-control': 'no-store',
  });
  createReadStream(path).pipe(res);
}).listen(PORT, () => {
  console.log(`Serving ${ROOT} on http://localhost:${PORT}/`);
});
